#!/usr/bin/env python3
"""Builds Script Lab's Python library and templates into the app.

Run after editing Tools/script-lab/prism_gp.py or Tools/script-lab/templates/*.py:
    python3 scripts/sync-script-lab.py
It rewrites Sources/EthersPrismCore/ScriptLab/ScriptLabResources.swift.
"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
lab = root / "Tools" / "script-lab"
lib = (lab / "prism_gp.py").read_text(encoding="utf-8")
assert '"""###' not in lib
templates = sorted((lab / "templates").glob("*.py"))
parts = [
    "// Generated by scripts/sync-script-lab.py from Tools/script-lab. Don't edit by hand.\n\n",
    "extension ScriptLab {\n",
    "    /// The prism_gp library, written next to every script Script Lab runs.\n",
    '    public static let library = ###"""\n', lib.rstrip("\n"), '\n"""###\n\n',
    "    /// Built-in templates: (name, code).\n",
    "    public static let templates: [(name: String, code: String)] = [\n",
]
for t in templates:
    code = t.read_text(encoding="utf-8")
    assert '"""###' not in code
    name = t.stem.split(" ", 1)[1] if t.stem[0].isdigit() else t.stem
    parts += ['        ("', name.replace('"', '\\"'), '", ###"""\n', code.rstrip("\n"), '\n"""###),\n']
parts += ["    ]\n", "}\n"]
out = root / "Sources/EthersPrismCore/ScriptLab/ScriptLabResources.swift"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("".join(parts), encoding="utf-8")
print("Updated", out.name, "with", len(templates), "templates")
